// Edit this list to change what the workflow searches for.
// Each search costs 1 API request (free plan: 200/month). 3 searches/day = ~90/month.
const searches = [
  { query: 'data analyst in Medellín, Colombia', country: 'co' },
  { query: 'analista de datos in Colombia',      country: 'co' },
  { query: 'junior data analyst remote Latin America', country: 'us' },
];

return searches.map(s => ({
  json: { ...s, page: 1, num_pages: 1, date_posted: '3days' },
}));

// Turns every JSearch response into one clean list of jobs.
const jobs = [];

for (const item of $input.all()) {
  const data = Array.isArray(item.json.data) ? item.json.data : [];

  for (const j of data) {
    if (!j.job_title || !j.employer_name || !j.job_apply_link) continue;

    const location =
      j.job_location ||
      [j.job_city, j.job_state, j.job_country].filter(Boolean).join(', ') ||
      null;

    jobs.push({
      external_id: j.job_id ?? null,
      title: String(j.job_title).trim(),
      company: String(j.employer_name).trim(),
      location,
      work_mode: j.job_is_remote ? 'remote' : 'unknown',
      url: j.job_apply_link,
      description: j.job_description ?? null,
      posted_at: j.job_posted_at_datetime_utc ?? null,
      publisher: j.job_publisher ?? null,
      salary_min: j.job_min_salary ?? null,
      salary_max: j.job_max_salary ?? null,
      salary_currency: j.job_salary_currency ?? null,
      salary_period: j.job_salary_period ?? null,
    });
  }
}

return [{ json: { jobs, fetched: jobs.length } }];
